LevelDefinition _buildFrozenLevel({
  required JourneyGeneratedSource source,
  required LevelDifficulty difficulty,
  required int difficultyScore,
  required List<int> colors,
  required List<int> initialIndices,
}) {
  final id = 'level_${source.journeyLevelNumber.toString().padLeft(3, '0')}';
  final solution = List.generate(
    colors.length,
    (index) => '${id}_tile_$index',
    growable: false,
  );
  return LevelDefinition(
    id: id,
    number: source.journeyLevelNumber,
    nameKey: 'numberedLevel',
    boardSize: source.boardSize,
    difficulty: difficulty,
    difficultyScore: difficultyScore,
    tiles: List.generate(
      colors.length,
      (index) => LevelTileDefinition(
        id: '${id}_tile_$index',
        colorValue: colors[index],
      ),
      growable: false,
    ),
    initialTileOrder: [for (final index in initialIndices) solution[index]],
    solutionTileOrder: solution,
  );
}
